using Azure.Search.Documents;using Azure.Search.Documents.Models;
public sealed record SearchQuery(string Query,int TopK=10);
public sealed record SearchHit(string DocumentId,string VersionId,string Text,double Score,string Citation);
public interface IQueryEmbeddingProvider{Task<float[]> EmbedAsync(string text,CancellationToken ct=default);}
public static class SearchFilterBuilder{public static string Build(Guid tenantId,Guid userId)=>$"TenantId eq '{tenantId}' and (not AllowedPrincipalIds/any() or AllowedPrincipalIds/any(p: p eq '{userId}'))";}
public sealed class HybridSearchApplication(SearchClient client,IQueryEmbeddingProvider embeddings){public async Task<IReadOnlyList<SearchHit>> SearchAsync(Guid tenantId,Guid userId,SearchQuery request,CancellationToken ct=default){if(tenantId==Guid.Empty)throw new UnauthorizedAccessException();if(string.IsNullOrWhiteSpace(request.Query))throw new ArgumentException("Query is required");if(request.TopK is <1 or >50)throw new ArgumentOutOfRangeException(nameof(request.TopK));var vector=await embeddings.EmbedAsync(request.Query,ct);var options=new SearchOptions{Size=request.TopK,Filter=SearchFilterBuilder.Build(tenantId,userId)};options.Select.Add("DocumentId");options.Select.Add("VersionId");options.Select.Add("Text");options.Select.Add("Citation");options.VectorSearch=new VectorSearchOptions{Queries={new VectorizedQuery(vector){KNearestNeighborsCount=Math.Max(request.TopK,10),Fields={"ContentVector"}}}};var response=await client.SearchAsync<SearchDocument>(request.Query,options,ct);var hits=new List<SearchHit>();await foreach(var item in response.Value.GetResultsAsync()){var d=item.Document;hits.Add(new(d.GetString("DocumentId")??string.Empty,d.GetString("VersionId")??string.Empty,d.GetString("Text")??string.Empty,item.Score??0d,d.GetString("Citation")??string.Empty));}return hits;}}
public sealed class HttpQueryEmbeddingProvider(HttpClient http,IConfiguration config):IQueryEmbeddingProvider{public async Task<float[]> EmbedAsync(string text,CancellationToken ct=default){var endpoint=config["AzureOpenAI:Endpoint"]?.TrimEnd('/')??throw new InvalidOperationException("AzureOpenAI:Endpoint missing");var deployment=config["AzureOpenAI:EmbeddingDeployment"]??throw new InvalidOperationException("AzureOpenAI:EmbeddingDeployment missing");using var req=new HttpRequestMessage(HttpMethod.Post,$"{endpoint}/openai/deployments/{deployment}/embeddings?api-version=2024-10-21");var key=config["AzureOpenAI:ApiKey"];if(!string.IsNullOrWhiteSpace(key))req.Headers.Add("api-key",key);req.Content=JsonContent.Create(new{input=text});using var res=await http.SendAsync(req,ct);res.EnsureSuccessStatusCode();using var doc=await System.Text.Json.JsonDocument.ParseAsync(await res.Content.ReadAsStreamAsync(ct),cancellationToken:ct);return doc.RootElement.GetProperty("data")[0].GetProperty("embedding").EnumerateArray().Select(x=>x.GetSingle()).ToArray();}}